/**
 * Builds the plugin's two generated files, code.js and ui.html, from their sources.
 *
 *   node plugin/build.mjs           writes code.js and ui.html next to this file
 *   node plugin/build.mjs --check   writes nothing; exits 1 when either file is out of date
 *
 * code.js is src/main.js with two things put in:
 *   - the generator's data reader: ../data-file.mjs and src/release.mjs, as one function
 *   - the runtime: ../runtime.js, word for word, as the body of applyData
 * ui.html is src/ui.html with src/sources.mjs put in.
 *
 * The sources are plain modules that Node tests import. To run in Figma they are copied in as text
 * with two mechanical changes: an `import` of another bundled module is dropped, and an `import` of a
 * constant from settings.mjs or codegen.mjs becomes that constant's value. `export` is removed. Any
 * other import or export form stops the build, so a change that this copying cannot carry is found
 * here and not in Figma.
 *
 * Run it after changing runtime.js, data-file.mjs, settings.mjs or anything under src/. A test fails
 * while the committed files differ from what this builds.
 */
import { readFileSync, writeFileSync } from "node:fs";
import { fileURLToPath } from "node:url";

const here = new URL("./", import.meta.url);
const read = (relative) => readFileSync(new URL(relative, here), "utf8");

/** Modules whose code is bundled, so an import of one is dropped. */
const BUNDLED = new Set(["../../data-file.mjs"]);
/** Modules a bundled module takes constants from. The build reads their values. */
const CONSTANTS = new Set(["../../settings.mjs", "../../codegen.mjs", "./settings.mjs", "./codegen.mjs"]);

const IMPORT = /^import\s*\{([^}]*)\}\s*from\s*"([^"]+)";[ \t]*\r?\n/gm;

/** A module's text, ready to sit inside a function: imports resolved, `export` removed. */
async function inline(source, base) {
  let out = "";
  let last = 0;
  for (const match of source.matchAll(IMPORT)) {
    out += source.slice(last, match.index);
    last = match.index + match[0].length;
    const names = match[1].split(",").map((name) => name.trim()).filter(Boolean);
    const specifier = match[2];
    if (BUNDLED.has(specifier)) continue;
    if (!CONSTANTS.has(specifier)) throw new Error(`build.mjs cannot carry the import of "${specifier}" into the plugin.`);
    const module = await import(new URL(specifier, new URL(base, here)).href);
    for (const name of names) {
      if (!(name in module) || typeof module[name] === "function") throw new Error(`build.mjs: "${name}" from "${specifier}" is not a constant it can copy.`);
      out += `const ${name} = ${JSON.stringify(module[name])};\n`;
    }
  }
  out += source.slice(last);
  if (/^\s*import\b/m.test(out)) throw new Error("build.mjs: a module has an import it does not handle.");
  if (/^\s*export\s+(default\b|\{|\*)/m.test(out)) throw new Error("build.mjs: a module has an export form it does not handle.");
  return out.replace(/^export\s+(async\s+function|function|class|const|let|var)\b/gm, "$1");
}

const HEADER = [
  "// GENERATED by plugin/build.mjs. Do not edit this file.",
  "// Sources: plugin/src/main.js, plugin/src/release.mjs, ../data-file.mjs (the reader) and ../runtime.js (the runtime).",
  "// To change it, change a source and run: node plugin/build.mjs",
  "",
].join("\n");

function put(template, marker, text) {
  const line = `/* @bundle:${marker} */`;
  if (template.split(line).length !== 2) throw new Error(`build.mjs: ${line} must appear exactly once.`);
  return template.replace(line, () => text);
}

/** The text of code.js and ui.html. */
export async function buildPlugin() {
  const dataFile = await inline(read("../data-file.mjs"), "../data-file.mjs");
  const release = await inline(read("./src/release.mjs"), "./src/release.mjs");
  const reader = [
    "function createReader() {",
    dataFile.trimEnd(),
    release.trimEnd(),
    "  return { loadRelease: loadRelease, readData: readData, ReleaseError: ReleaseError, DataError: DataError };",
    "}",
    "const reader = createReader();",
    "",
  ].join("\n");
  const runtime = read("../runtime.js");

  let code = read("./src/main.js");
  code = put(code, "reader", reader);
  code = put(code, "runtime", runtime.trimEnd() + "\n");

  const sources = await inline(read("./src/sources.mjs"), "./src/sources.mjs");
  if (/<\/script/i.test(sources)) throw new Error("build.mjs: sources.mjs must not contain </script.");
  const ui = put(read("./src/ui.html"), "sources", sources.trimEnd());

  return { "code.js": HEADER + code, "ui.html": ui };
}

async function main() {
  const built = await buildPlugin();
  const check = process.argv.includes("--check");
  let stale = 0;
  for (const [name, text] of Object.entries(built)) {
    const target = new URL(name, here);
    let current = null;
    try {
      current = readFileSync(target, "utf8");
    } catch {
      current = null;
    }
    if (current === text) continue;
    stale += 1;
    if (check) console.error(`plugin/${name} is out of date. Run: node plugin/build.mjs`);
    else writeFileSync(target, text);
  }
  if (check && stale > 0) process.exitCode = 1;
  else if (!check) console.log(`Wrote plugin/code.js and plugin/ui.html${stale === 0 ? " (no change)" : ""}.`);
}

if (process.argv[1] === fileURLToPath(import.meta.url)) await main();
